#include "sector_ai_page.hpp"
#include "request_authorization_widget.hpp"
#include "sector_research_model.hpp"
#include <QtWidgets>
SectorAiPage::SectorAiPage(Json input,Json preferences,Scopes current,QString file,SectorResearchStore* storage,QWidget*parent,Authorize auth,Fixture test,QNetworkAccessManager*fake):QWidget(parent),freezeInput(input),prefs(preferences),scopes(current),businessFile(file),store(storage),authorize(auth),fixture(test),runner(this,fake){
 setObjectName("sectorAiPage");auto layout=new QVBoxLayout(this);layout->addWidget(new QLabel("板块 / 产业完整材料报告",this));status=new QLabel("尚未执行。默认无本次授权和凭据；不会自动发送资料。",this);status->setObjectName("sectorAiStatus");status->setWordWrap(true);layout->addWidget(status);
 auto actions=new QHBoxLayout;layout->addLayout(actions);auto button=[&](QString name,QString label,std::function<void()> fn){auto b=new QPushButton(label,this);b->setObjectName(name);actions->addWidget(b);connect(b,&QPushButton::clicked,this,[=]{if(!live())return;try{fn();}catch(const std::exception&e){status->setText(QString::fromUtf8(e.what()));}});};
 tabs=new QTabWidget(this);layout->addWidget(tabs,1);auto reader=[&](QString name,QString title){auto r=new QPlainTextEdit(this);r->setReadOnly(true);r->setObjectName(name);tabs->addTab(r,title);return r;};source=reader("sectorAiSource","完整材料");preview=reader("sectorAiPreview","完整外发预览");report=reader("sectorAiReport","候选与历史");
 consent=new QCheckBox("已阅读完整外发内容；执行仍需独立授权。保存报告代表保留未核验候选。",this);consent->setObjectName("sectorAiConsent");layout->addWidget(consent);
 if(!authorize){authority=new RequestAuthorizationWidget([this]{return live();},this);layout->insertWidget(2,authority);authorize=[this](const aiKnowledge::Prepared&r){return Access{authority->authorize(r),[this]{return authority->acquire();}};};authority->expired=[this]{cancel();};}
 button("sectorAiPrepare","冻结并预览",[=]{cancel();prepared.reset();source->clear();preview->clear();report->clear();plan=freezeInput();sectorAi::validatePlan(plan);source->setPlainText(sectorAi::readPlan(plan));tabs->setCurrentWidget(source);prepared=std::make_unique<aiKnowledge::Prepared>(sectorAi::request(plan,prefs?prefs():QJsonObject{}));preview->setPlainText(QString::fromUtf8(QJsonDocument(prepared->preview()).toJson()));if(authority)authority->bind({*prepared});status->setText("材料已完整冻结。请阅读外发预览，尚未执行。");});
 button("sectorAiExecute","执行已授权请求",[=]{if(!prepared||!consent->isChecked())throw std::runtime_error("请先冻结、阅读并确认完整预览");if(busy)throw std::runtime_error("请求正在执行");if(freezeInput()!=plan)throw std::runtime_error("主题或完整材料已变化，请重新冻结");candidate={};busy=true;auto ticket=++epoch;consent->setChecked(false);try{Access access=authorize?authorize(*prepared):Access{};if(ticket!=epoch||!live())throw std::runtime_error("页面已离开，未执行");status->setText("正在核验本次授权并执行；不会自动重试。");QPointer<SectorAiPage> self(this);auto done=[self,ticket](QJsonObject attempt){if(self)self->accept(ticket,attempt);};if(fixture)fixture(*prepared,done);else runner.start(*prepared,access.grant,access.credential,done);}catch(...){cancel();throw;}});
 button("sectorAiCancel","取消",[=]{cancel();status->setText("已取消待执行/待保存资格；已有历史保留。");});
 button("sectorAiSave","确认保存候选",[=]{if(candidate.isEmpty()||!consent->isChecked()||busy)throw std::runtime_error("请完整阅读有效候选并再次确认");auto record=candidate;store->saveAiReport(record,businessFile,scopes,[this]{return !live();});candidate={};consent->setChecked(false);status->setText("报告已保存；结论仍未核验。");try{refreshHistory();}catch(...){status->setText("报告已保存；历史刷新失败，请重新打开。");}});
 history=new QComboBox(this);history->setObjectName("sectorAiHistory");layout->addWidget(history);connect(history,qOverload<int>(&QComboBox::activated),this,[=](int){if(!live())return;try{cancel();auto r=store->aiReport(history->currentData().toString());sectorAi::validateRecord(r);source->setPlainText(sectorAi::readPlan(r["plan"].toObject()));preview->setPlainText(QString::fromUtf8(QJsonDocument(r["requestPreview"].toObject()).toJson()));report->setPlainText(sectorAi::readReport(r));viewedHistoryId=r["id"].toString();tabs->setCurrentWidget(report);status->setText("正在阅读完整历史；不会恢复执行或保存许可。");}catch(const std::exception&e){status->setText(e.what());}});refreshHistory();
 connect(qApp,&QGuiApplication::applicationStateChanged,this,[this](Qt::ApplicationState state){if(state!=Qt::ApplicationActive)cancel();});
 button("sectorAiReview","复核所读报告关系",[this]{if(viewedHistoryId.isEmpty()||history->currentData().toString()!=viewedHistoryId||!onReview)throw std::runtime_error("先打开要复核的完整报告历史");onReview(viewedHistoryId);});
 button("sectorAiBack","返回材料页",[this]{cancel();if(onBack)onBack();});
}
bool SectorAiPage::live()const{return isVisible()&&window()->isVisible()&&!window()->isMinimized()&&QGuiApplication::applicationState()==Qt::ApplicationActive;}
void SectorAiPage::accept(quint64 ticket,const QJsonObject&a){if(ticket!=epoch||!live())return;busy=false;if(authority)authority->clear();try{if(fixture&&(a["provenance"]!="local-fixture"||a["networkAttempted"]!=false))throw std::runtime_error("受控夹具不能冒充在线执行");if(a["status"]!="completed"){candidate={};status->setText("未生成报告："+a["status"].toString()+" / "+a["errorCode"].toString());return;}candidate=sectorAi::completed(plan,prepared->preview(),a);report->setPlainText(sectorAi::readReport(candidate));tabs->setCurrentWidget(report);status->setText("完整返回已校验，尚未保存；请阅读候选并明确确认。");}catch(const std::exception&e){candidate={};status->setText(QString::fromUtf8(e.what()));}}
void SectorAiPage::refreshHistory(){QSignalBlocker block(history);history->clear();for(auto id:store->aiReportIds())history->addItem(id,id);}

void SectorAiPage::cancel(){if(authority)authority->clear();viewedHistoryId.clear();++epoch;busy=false;candidate={};if(consent)consent->setChecked(false);runner.cancel();}
void SectorAiPage::hideEvent(QHideEvent*e){cancel();QWidget::hideEvent(e);}
SectorAiPage::~SectorAiPage(){cancel();}
